const body = $json.body ?? $json;

const acao = String(body.acao ?? '').trim().toLowerCase();
const dados = body.dados ?? {};

const erros = [];

// =====================================================
// AÇÕES DO COMMERCEAI
// =====================================================
//
// Ações já implementadas:
// - cadastrar_cliente
// - consultar_cliente
// - alterar_cliente
// - cadastrar_produto
// - consultar_produto
//
// Ações planejadas:
// - alterar_produto
// - cadastrar_venda
// - consultar_venda
// - cadastrar_compra
// - consultar_compra
// - consultar_estoque
// - movimentar_estoque
// - dashboard
// - relatorios
//
// =====================================================

const acoesPermitidas = [

  // CLIENTES
  'cadastrar_cliente',
  'consultar_cliente',
  'alterar_cliente',

  // PRODUTOS
  'cadastrar_produto',
  'consultar_produto',
  'alterar_produto',

  // VENDAS
  'cadastrar_venda',
  'consultar_venda',

  // COMPRAS
  'cadastrar_compra',
  'consultar_compra',

  // ESTOQUE
  'consultar_estoque',
  'movimentar_estoque',

  // OUTROS
  'dashboard',
  'relatorios'
];

// =====================================================
// VALIDAÇÃO DA AÇÃO
// =====================================================

if (!acao) {
  erros.push(
    'O campo "acao" é obrigatório.'
  );
}

if (
  acao &&
  !acoesPermitidas.includes(acao)
) {
  erros.push(
    `Ação "${acao}" não é suportada.`
  );
}

// =====================================================
// VALIDAÇÃO DOS DADOS
// =====================================================

if (
  !body.dados ||
  typeof body.dados !== 'object' ||
  Array.isArray(body.dados)
) {
  erros.push(
    'O campo "dados" é obrigatório e deve ser um objeto.'
  );
}

// =====================================================
// VALIDAÇÕES DE CLIENTE
// =====================================================

if (acao === 'cadastrar_cliente') {

  const nomeCadastro =
    dados.Nome ??
    dados.nome ??
    null;

  if (
    !nomeCadastro ||
    String(nomeCadastro).trim() === ''
  ) {
    erros.push(
      'O campo "nome" é obrigatório para cadastrar um cliente.'
    );
  }

  const emailCadastro =
    dados['E-mail'] ??
    dados.Email ??
    dados.email ??
    null;

  if (
    !emailCadastro ||
    String(emailCadastro).trim() === ''
  ) {
    erros.push(
      'O campo "email" é obrigatório para cadastrar um cliente.'
    );
  }
}

// =====================================================
// CONSULTAR / ALTERAR CLIENTE
// =====================================================

if (
  acao === 'consultar_cliente' ||
  acao === 'alterar_cliente'
) {

  if (
    !dados.IdCliente &&
    !dados.id
  ) {
    erros.push(
      'O campo "IdCliente" é obrigatório.'
    );
  }
}

// =====================================================
// VALIDAÇÃO DE E-MAIL
// =====================================================

const emailDados =
  dados['E-mail'] ??
  dados.Email ??
  dados.email ??
  null;

if (emailDados) {

  const email = String(emailDados).trim();

  const emailValido =
    /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email);

  if (!emailValido) {
    erros.push(
      'O formato do e-mail é inválido.'
    );
  }
}

// =====================================================
// VALIDAÇÕES DE PRODUTO
// =====================================================

if (acao === 'cadastrar_produto') {

  const nomeProduto =
    dados.Nome ??
    dados.nome ??
    null;

  const precoProduto =
    dados.Preco ??
    dados.preco ??
    null;

  const estoqueProduto =
    dados.Estoque ??
    dados.estoque ??
    null;

  // ---------------------------------------------------
  // Nome
  // ---------------------------------------------------

  if (
    !nomeProduto ||
    String(nomeProduto).trim() === ''
  ) {
    erros.push(
      'O campo "nome" é obrigatório para cadastrar um produto.'
    );
  }

  // ---------------------------------------------------
  // Preço
  // ---------------------------------------------------

  if (
    precoProduto === null ||
    precoProduto === undefined ||
    precoProduto === ''
  ) {

    erros.push(
      'O campo "preco" é obrigatório para cadastrar um produto.'
    );

  } else if (
    isNaN(Number(precoProduto))
  ) {

    erros.push(
      'O campo "preco" deve ser um número.'
    );
  }

  // ---------------------------------------------------
  // Estoque
  // ---------------------------------------------------

  if (
    estoqueProduto === null ||
    estoqueProduto === undefined ||
    estoqueProduto === ''
  ) {

    erros.push(
      'O campo "estoque" é obrigatório para cadastrar um produto.'
    );

  } else if (
    isNaN(Number(estoqueProduto))
  ) {

    erros.push(
      'O campo "estoque" deve ser um número.'
    );
  }
}

// =====================================================
// CONSULTAR PRODUTO
// =====================================================
//
// A consulta pode utilizar qualquer um dos critérios:
//
// - IdProduto
// - Nome
// - SKU
// - Categoria
// - CodigoBarras
//
// Pelo menos um critério deve ser informado.
//
// =====================================================

if (acao === 'consultar_produto') {

  const idProduto =
    dados.IdProduto ??
    dados.idProduto ??
    dados.id ??
    null;

  const nomeProduto =
    dados.Nome ??
    dados.nome ??
    null;

  const skuProduto =
    dados.SKU ??
    dados.sku ??
    null;

  const categoriaProduto =
    dados.Categoria ??
    dados.categoria ??
    null;

  const codigoBarrasProduto =
    dados.CodigoBarras ??
    dados.codigoBarras ??
    dados.codigo_barras ??
    null;

  const possuiCriterio = [
    idProduto,
    nomeProduto,
    skuProduto,
    categoriaProduto,
    codigoBarrasProduto
  ].some(
    valor =>
      valor !== null &&
      valor !== undefined &&
      String(valor).trim() !== ''
  );

  if (!possuiCriterio) {

    erros.push(
      'Informe pelo menos um critério para consultar o produto: IdProduto, Nome, SKU, Categoria ou CodigoBarras.'
    );
  }
}

// =====================================================
// ALTERAR PRODUTO
// =====================================================

if (acao === 'alterar_produto') {

  const idProduto =
    dados.IdProduto ??
    dados.idProduto ??
    dados.id ??
    null;

  if (!idProduto) {

    erros.push(
      'O campo "IdProduto" é obrigatório para alterar um produto.'
    );
  }
}

// =====================================================
// NORMALIZAÇÃO DOS DADOS
// =====================================================

let dadosNormalizados = {};

// =====================================================
// CLIENTES
// =====================================================

if (
  acao === 'cadastrar_cliente' ||
  acao === 'consultar_cliente' ||
  acao === 'alterar_cliente'
) {

  dadosNormalizados = {

    IdCliente:
      dados.IdCliente ??
      dados.id ??
      null,

    Nome:
      dados.Nome ??
      dados.nome ??
      null,

    Email:
      dados['E-mail'] ??
      dados.Email ??
      dados.email ??
      null,

    Telefone:
      dados.Telefone ??
      dados.telefone ??
      null,

    Status:
      dados.Status ??
      dados.status ??
      null
  };
}

// =====================================================
// CADASTRAR PRODUTO
// =====================================================

else if (
  acao === 'cadastrar_produto'
) {

  dadosNormalizados = {

    Nome:
      dados.Nome ??
      dados.nome ??
      null,

    Descricao:
      dados.Descricao ??
      dados.descricao ??
      null,

    Preco:
      dados.Preco ??
      dados.preco ??
      null,

    Estoque:
      dados.Estoque ??
      dados.estoque ??
      null,

    Categoria:
      dados.Categoria ??
      dados.categoria ??
      null,

    CodigoBarras:
      dados.CodigoBarras ??
      dados.codigoBarras ??
      dados.codigo_barras ??
      null,

    SKU:
      dados.SKU ??
      dados.sku ??
      null
  };
}

// =====================================================
// CONSULTAR PRODUTO
// =====================================================

else if (
  acao === 'consultar_produto'
) {

  dadosNormalizados = {

    IdProduto:
      dados.IdProduto ??
      dados.idProduto ??
      dados.id ??
      null,

    Nome:
      dados.Nome ??
      dados.nome ??
      null,

    SKU:
      dados.SKU ??
      dados.sku ??
      null,

    Categoria:
      dados.Categoria ??
      dados.categoria ??
      null,

    CodigoBarras:
      dados.CodigoBarras ??
      dados.codigoBarras ??
      dados.codigo_barras ??
      null
  };
}

// =====================================================
// ALTERAR PRODUTO
// =====================================================

else if (
  acao === 'alterar_produto'
) {

  dadosNormalizados = {

    IdProduto:
      dados.IdProduto ??
      dados.idProduto ??
      dados.id ??
      null,

    Nome:
      dados.Nome ??
      dados.nome ??
      null,

    Descricao:
      dados.Descricao ??
      dados.descricao ??
      null,

    Preco:
      dados.Preco ??
      dados.preco ??
      null,

    Estoque:
      dados.Estoque ??
      dados.estoque ??
      null,

    Categoria:
      dados.Categoria ??
      dados.categoria ??
      null,

    CodigoBarras:
      dados.CodigoBarras ??
      dados.codigoBarras ??
      dados.codigo_barras ??
      null,

    SKU:
      dados.SKU ??
      dados.sku ??
      null
  };
}

// =====================================================
// AÇÕES FUTURAS
// =====================================================
//
// Estas ações já são reconhecidas pelo sistema,
// mas ainda não possuem normalização específica.
//
// Quando implementarmos cada módulo,
// adicionaremos aqui os campos correspondentes.
//
// =====================================================

else if (
  acao === 'cadastrar_venda' ||
  acao === 'consultar_venda' ||
  acao === 'cadastrar_compra' ||
  acao === 'consultar_compra' ||
  acao === 'consultar_estoque' ||
  acao === 'movimentar_estoque' ||
  acao === 'dashboard' ||
  acao === 'relatorios'
) {

  dadosNormalizados = {
    ...dados
  };
}

// =====================================================
// RETORNO
// =====================================================

return [
  {
    json: {

      sucesso:
        erros.length === 0,

      acao,

      dados:
        dadosNormalizados,

      erros
    }
  }
];

