SELECT
    IdProduto,
    Nome,
    Descricao,
    Preco,
    Estoque,
    Categoria,
    CodigoBarras,
    SKU,
    DataCadastro,
    Ativo
FROM Produtos
WHERE
    (
        {{ $json.dados.IdProduto === null
            ? '1=1'
            : `IdProduto = ${Number($json.dados.IdProduto)}`
        }}
    )
    AND
    (
        {{ $json.dados.Nome === null
            ? '1=1'
            : `Nome LIKE '%${$json.dados.Nome.replace(/'/g, "''")}%'`
        }}
    )
    AND
    (
        {{ $json.dados.SKU === null
            ? '1=1'
            : `SKU = '${$json.dados.SKU.replace(/'/g, "''")}'`
        }}
    )
    AND
    (
        {{ $json.dados.Categoria === null
            ? '1=1'
            : `Categoria LIKE '%${$json.dados.Categoria.replace(/'/g, "''")}%'`
        }}
    )
    AND
    (
        {{ $json.dados.CodigoBarras === null
            ? '1=1'
            : `CodigoBarras = '${$json.dados.CodigoBarras.replace(/'/g, "''")}'`
        }}
    );

